// Read the single canonical SQL result set generated by node run.mjs.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outDir = join(root, 'dashboard');
mkdirSync(outDir, { recursive: true });
const q = JSON.parse(readFileSync(join(root, 'results/results.json'), 'utf8'));
const monthly = q.q05_monthly_gmv_cum.filter(r => r.ym < '2018-09');
const delivery = q.q09_delivery_vs_review.map(r => ({...r, bucket:r.delivery_bucket, bad_pct:r.bad_review_pct}));
const categories = q.q10_category_share;
const states = q.q01_state_gmv;
const funnel = q.q06_funnel[0];
const repeat = {...q.q02_repeat_users[0], total:q.q02_repeat_users[0].total_users};
const cohort = q.q07_cohort_return.map(r => ({cohort:r.cohort_month, users:r.cohort_users, returned:r.returned_users, rate:r.return_rate_pct}));
const fmt = n => n.toLocaleString('zh-CN', { maximumFractionDigits: 0 });
const money = n => (n / 1000000).toFixed(2) + 'M';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

function lineChart(rows, w = 520, h = 220) {
  const pad = { l: 56, r: 12, t: 14, b: 34 };
  const max = Math.max(...rows.map(r => r.gmv));
  const iw = w - pad.l - pad.r, ih = h - pad.t - pad.b;
  const x = i => pad.l + (iw * i) / (rows.length - 1);
  const y = v => pad.t + ih - (ih * v) / max;
  const path = rows.map((r, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(r.gmv).toFixed(1)}`).join(' ');
  const grid = [0, 0.25, 0.5, 0.75, 1].map(f => {
    const yy = pad.t + ih - ih * f;
    return `<line x1="${pad.l}" y1="${yy}" x2="${w - pad.r}" y2="${yy}" stroke="#e6e9ef" stroke-width="1"/>
      <text x="${pad.l - 8}" y="${yy + 4}" text-anchor="end" font-size="10" fill="#8a93a5">${money(max * f)}</text>`;
  }).join('');
  const labels = rows.map((r, i) => (i % 4 === 0 ? `<text x="${x(i)}" y="${h - 10}" text-anchor="middle" font-size="10" fill="#8a93a5">${r.ym.slice(2)}</text>` : '')).join('');
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}">${grid}
    <path d="${path}" fill="none" stroke="#2f6fed" stroke-width="2.2"/>
    <path d="${path} L${x(rows.length - 1)},${pad.t + ih} L${pad.l},${pad.t + ih} Z" fill="#2f6fed" opacity="0.08"/>
    ${labels}</svg>`;
}

function barChart(rows, key, val, w = 520, h = 220, color = '#e0653a') {
  const pad = { l: 56, r: 12, t: 14, b: 34 };
  const max = Math.max(...rows.map(r => r[val]));
  const iw = w - pad.l - pad.r, ih = h - pad.t - pad.b;
  const bw = iw / rows.length * 0.55;
  const bars = rows.map((r, i) => {
    const cx = pad.l + (iw * (i + 0.5)) / rows.length;
    const bh = (ih * r[val]) / max;
    const yy = pad.t + ih - bh;
    return `<rect x="${cx - bw / 2}" y="${yy}" width="${bw}" height="${bh}" fill="${color}" rx="3"/>
      <text x="${cx}" y="${yy - 5}" text-anchor="middle" font-size="10.5" fill="#3c4457">${r[val]}</text>
      <text x="${cx}" y="${h - 10}" text-anchor="middle" font-size="10" fill="#8a93a5">${esc(r[key])}</text>`;
  }).join('');
  const grid = [0, 0.5, 1].map(f => {
    const yy = pad.t + ih - ih * f;
    return `<line x1="${pad.l}" y1="${yy}" x2="${w - pad.r}" y2="${yy}" stroke="#e6e9ef"/>
      <text x="${pad.l - 8}" y="${yy + 4}" text-anchor="end" font-size="10" fill="#8a93a5">${(max * f).toFixed(0)}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}">${grid}${bars}</svg>`;
}

function hBarChart(rows, key, val, w = 520, h = 260, color = '#2f9e7a') {
  const pad = { l: 150, r: 60, t: 8, b: 8 };
  const max = Math.max(...rows.map(r => r[val]));
  const ih = h - pad.t - pad.b;
  const bh = ih / rows.length * 0.6;
  const bars = rows.map((r, i) => {
    const cy = pad.t + (ih * (i + 0.5)) / rows.length;
    const bw = ((w - pad.l - pad.r) * r[val]) / max;
    return `<rect x="${pad.l}" y="${cy - bh / 2}" width="${bw}" height="${bh}" fill="${color}" rx="3"/>
      <text x="${pad.l - 8}" y="${cy + 4}" text-anchor="end" font-size="10.5" fill="#3c4457">${esc(r[key])}</text>
      <text x="${pad.l + bw + 6}" y="${cy + 4}" font-size="10" fill="#8a93a5">${money(r[val])}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}">${bars}</svg>`;
}

function funnelChart(f, w = 520, h = 200) {
  const stages = [['下单', f.placed], ['支付通过', f.approved], ['已发货', f.shipped], ['已签收', f.delivered]];
  const max = stages[0][1];
  const ih = (h - 20) / stages.length;
  const rows = stages.map((s, i) => {
    const bw = (w - 220) * (s[1] / max);
    const yy = 10 + ih * i;
    return `<rect x="120" y="${yy}" width="${bw}" height="${ih - 10}" fill="#2f6fed" opacity="${1 - i * 0.16}" rx="4"/>
      <text x="112" y="${yy + ih / 2}" text-anchor="end" font-size="11" fill="#3c4457">${s[0]}</text>
      <text x="${124 + bw}" y="${yy + ih / 2}" font-size="11" fill="#3c4457">${fmt(s[1])}（${((s[1] / max) * 100).toFixed(2)}%）</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}">${rows}</svg>`;
}

function cohortTable(rows) {
  const head = '<tr><th>首单月份</th><th>首单人数</th><th>回流人数</th><th>回流率</th></tr>';
  const body = rows.map(r => `<tr><td>${r.cohort}</td><td>${fmt(r.users)}</td><td>${fmt(r.returned)}</td><td>${r.rate}%</td></tr>`).join('');
  return `<table class="tbl">${head}${body}</table>`;
}

const kpi = (label, value, sub) =>
  `<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-sub">${sub}</div></div>`;

const totalGmv = monthly.reduce((s, r) => s + r.gmv, 0);

const html = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8">
<title>Olist 电商经营看板</title>
<style>
  :root { --ink:#1d2333; --muted:#8a93a5; --line:#e6e9ef; --bg:#f5f7fb; }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--bg); color:var(--ink);
         font-family:"Microsoft YaHei","PingFang SC","Segoe UI",sans-serif; }
  .wrap { max-width:1180px; margin:0 auto; padding:28px 20px 60px; }
  h1 { font-size:22px; margin:0 0 4px; }
  .sub { color:var(--muted); font-size:13px; margin-bottom:20px; }
  .kpis { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:16px; }
  .kpi { background:#fff; border:1px solid var(--line); border-radius:8px; padding:14px 16px; }
  .kpi-label { font-size:12px; color:var(--muted); }
  .kpi-value { font-size:24px; font-weight:700; margin:4px 0 2px; }
  .kpi-sub { font-size:12px; color:var(--muted); }
  .grid { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
  .card { background:#fff; border:1px solid var(--line); border-radius:8px; padding:16px; }
  .card h2 { font-size:14px; margin:0 0 2px; }
  .card p { font-size:12px; color:var(--muted); margin:0 0 10px; line-height:1.6; }
  .full { grid-column:1 / -1; }
  .tbl { width:100%; border-collapse:collapse; font-size:12px; }
  .tbl th, .tbl td { border-bottom:1px solid var(--line); padding:5px 8px; text-align:right; }
  .tbl th:first-child, .tbl td:first-child { text-align:left; }
  .tbl th { color:var(--muted); font-weight:600; }
  @media (max-width:820px){ .kpis{grid-template-columns:repeat(2,1fr);} .grid{grid-template-columns:1fr;} }
</style></head>
<body><div class="wrap">
  <h1>Olist 巴西电商经营看板</h1>
  <div class="sub">数据：99,441 笔订单 · 112,650 条明细 · 96,096 位客户 · 2016-09 至 2018-08 ｜ 数据源：Olist 公开数据集 ｜ 查询：SQLite（JOIN / CTE / 窗口函数）</div>

  <div class="kpis">
    ${kpi('含运费 GMV（BRL，趋势窗口）', money(totalGmv), '2016-09 至 2018-08')}
    ${kpi('订单签收率', funnel.delivered_rate_pct.toFixed(2) + '%', '下单 → 签收漏斗')}
    ${kpi('全期重复下单率', repeat.total ? ((100 * repeat.repeat_users) / repeat.total).toFixed(2) + '%' : '-', `${fmt(repeat.repeat_users)} / ${fmt(repeat.total)} 位客户`)}
    ${kpi('21 天以上订单差评率', delivery[3].bad_pct.toFixed(2) + '%', '已按订单去重；仅描述相关性')}
  </div>

  <div class="grid">
    <div class="card full">
      <h2>月度 GMV 趋势</h2>
      <p>金额单位 BRL（巴西雷亚尔）；商品价格加运费，剔除取消/不可用订单。末端稀疏月份不用于趋势判断；不能据峰值断言促销效果。</p>
      ${lineChart(monthly)}
    </div>

    <div class="card">
      <h2>配送时长 vs 差评率</h2>
      <p>每单仅保留最新答复的评价；按连续天数分桶。长配送组差评比例较高，尚未控制品类、地区等混杂因素。</p>
      ${barChart(delivery, 'bucket', 'bad_pct')}
    </div>

    <div class="card">
      <h2>订单漏斗</h2>
      <p>各阶段为时间戳非空比例，属于履约覆盖率；不是访客转化漏斗，也不足以判断履约成本或 SLA。</p>
      ${funnelChart(funnel)}
    </div>

    <div class="card">
      <h2>品类 GMV Top 10</h2>
      <p>与地区、月份、卖家分析采用同一有效订单和含运费金额口径。</p>
      ${hBarChart(categories, 'category', 'gmv')}
    </div>

    <div class="card">
      <h2>各州 GMV Top 10</h2>
      <p>按收货客户州分组；地理集中不直接等于可盈利的扩张机会。</p>
      ${hBarChart(states, 'state', 'gmv', 520, 260, '#5b6be0')}
    </div>

    <div class="card full">
      <h2>次月下单回流率</h2>
      <p>首单后下一自然月再次下单；只保留次月不晚于 2018-08 的 cohort，固定观察长度。统计所有下单状态，非成交复购。</p>
      ${cohortTable(cohort)}
    </div>
  </div>
</div></body></html>`;

writeFileSync(join(outDir, 'index.html'), html, 'utf8');
console.log('written dashboard/index.html');
